package dev.wildcraft.test;
import dev.wildcraft.client.animation.rig.*;
import dev.wildcraft.client.input.*;
import dev.wildcraft.combat.*;
import dev.wildcraft.fuse.*;
import dev.wildcraft.network.*;
import java.util.*;
import net.fabricmc.fabric.api.client.gametest.v1.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.minecraft.client.*;
import net.minecraft.client.gui.screens.inventory.InventoryScreen;
import net.minecraft.client.renderer.entity.state.AvatarRenderState;
import net.minecraft.client.resources.DefaultPlayerSkin;
import net.minecraft.core.BlockPos;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.player.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
import org.joml.Matrix4f;
import org.joml.Vector3f;
/** Native bow/item, idle art only; actual draw/release/arrow settlement retains the old paths. */
public final class BowIdleRigClientTest implements FabricClientGameTest {
    private static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    private static AvatarRenderState state(Minecraft c){return (AvatarRenderState)c.getEntityRenderDispatcher().getRenderer(c.player).createRenderState(c.player,1);}
    private static CombatRigLayer.Frame frame(Minecraft c){return state(c).getData(CombatRigLayer.FRAME);}
    private static PlayerSkin skin(PlayerModelType t){for(int i=0;i<100;i++){var s=DefaultPlayerSkin.get(new UUID(0,i));if(s.model()==t)return s;}throw new AssertionError("Skin fixture");}
    private static void prepare(ClientGameTestContext c,TestSingleplayerContext w,PlayerModelType type,HumanoidArm arm,boolean carry){
        c.getInput().releaseKey(v->v.keyUse);c.getInput().releaseKey(v->v.keyUp);c.getInput().releaseKey(WildcraftBindings.DEFEND);c.waitTicks(12);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.stopUsingItem();MeleeActions.receive(p,new MeleeIntent(MeleeIntent.CANCEL,(byte)0));p.teleportTo(p.level(),.5,120,.5,Set.of(),0,0,true);p.setDeltaMovement(Vec3.ZERO);p.setHealth(20);p.setInvulnerableTime(0);p.setMainArm(arm);p.getInventory().clearContent();p.getInventory().setSelectedSlot(0);p.setItemSlot(EquipmentSlot.CHEST,ItemStack.EMPTY);var bow=new ItemStack(Items.BOW);bow.set(net.minecraft.core.component.DataComponents.ENCHANTMENT_GLINT_OVERRIDE,true);p.setItemInHand(InteractionHand.MAIN_HAND,bow);p.getInventory().setItem(10,new ItemStack(Items.ARROW,32));var shield=new ItemStack(Items.SHIELD);shield.set(net.minecraft.core.component.DataComponents.BASE_COLOR,DyeColor.BLUE);shield.set(net.minecraft.core.component.DataComponents.ENCHANTMENT_GLINT_OVERRIDE,true);check(FusionItems.attach(shield,new ItemStack(Items.COBBLESTONE),s.registryAccess()),"Real carried shield Fuse");p.setItemInHand(InteractionHand.OFF_HAND,carry?shield:ItemStack.EMPTY);p.inventoryMenu.broadcastChanges();});c.waitFor(v->v.player.onGround()&&v.player.position().distanceTo(new Vec3(.5,120,.5))<.1&&v.player.getMainArm()==arm&&v.player.getMainHandItem().is(Items.BOW)&&v.player.getOffhandItem().isEmpty()==!carry);c.runOnClient(v->{v.player.setYRot(0);v.player.setXRot(0);RigAudit.fixture=skin(type);RigAudit.begin();});c.waitTicks(8);
    }
    private static Vector3f nativePoint(net.minecraft.client.renderer.item.ItemStackRenderState item,HumanoidArm arm,Vector3f raw){var layer=(dev.wildcraft.mixin.client.FusionLayerAccessor)((dev.wildcraft.mixin.client.FusionStateAccessor)item).wildcraft$layers()[0];var pose=new com.mojang.blaze3d.vertex.PoseStack();layer.wildcraft$transform().apply(arm==HumanoidArm.LEFT,pose.last());pose.mulPose(layer.wildcraft$local());return pose.last().pose().transformPosition(raw);}
    private static void grip(Minecraft c){var s=state(c);var f=s.getData(CombatRigLayer.FRAME);check(f!=null&&f.clip().startsWith("bow_idle_")&&f.weight()>.999,"Qualified actual full bow-idle pose");var arm=c.player.getMainArm();var item=s.getMainHandItemState();Matrix4f held;DodgeFeedbackAudit.checkingNativeItem=true;try{held=CombatRig.heldPose(f,item,arm,false);}finally{DodgeFeedbackAudit.checkingNativeItem=false;}
        Vector3f actual=held.transformPosition(nativePoint(item,arm,new Vector3f(.21875F,.46875F,.5F)));String side=arm==HumanoidArm.RIGHT?"right_":"left_";var names=Arrays.asList(f.data().bones());var target=new Matrix4f(CombatRigLayer.BASIS).mul(f.global()[names.indexOf(side+"sword_reference")]);var palm=new Matrix4f(CombatRigLayer.BASIS).mul(f.global()[names.indexOf(side+"palm_grip")]);check(actual.distance(target.getTranslation(new Vector3f()))<.00002&&actual.distance(palm.getTranslation(new Vector3f()))<.015,"Actual native sprite wood grip reaches adopted hand, not a reference bow mesh");
        var hi=held.transformPosition(nativePoint(item,arm,new Vector3f(.90625F,.84375F,.5F)));var lo=held.transformPosition(nativePoint(item,arm,new Vector3f(.15625F,.09375F,.5F)));check(hi.sub(lo).normalize().dot(target.transformDirection(new Vector3f(0,1,0)).normalize())>.99999,"Actual native sprite long axis matches source orientation");
    }
    @Override public void runTest(ClientGameTestContext c){try(TestSingleplayerContext w=c.worldBuilder().create()){
        w.getConnection().waitForChunksRender();w.getServer().runCommand("gamemode survival @p");w.getServer().runCommand("time set day");w.getServer().runOnServer(s->{for(int x=-8;x<=8;x++)for(int z=-8;z<=8;z++)s.overworld().setBlockAndUpdate(new BlockPos(x,119,z),Blocks.STONE.defaultBlockState());s.getPlayerList().getPlayers().getFirst().teleportTo(.5,120,.5);});c.waitFor(v->v.player.getY()>119);c.getInput().resizeWindow(1280,960);c.runOnClient(v->{v.options.guiScale().set(2);v.options.setCameraType(CameraType.THIRD_PERSON_FRONT);});c.waitFor(v->ActionInput.tickFrame().gameplay());
        for(var type:PlayerModelType.values())for(var arm:HumanoidArm.values())for(boolean carry:new boolean[]{false,true}){
            prepare(c,w,type,arm,carry);String expected="bow_idle_"+(carry?"carry":"empty")+"_"+(arm==HumanoidArm.RIGHT?"R":"L");c.waitFor(v->frame(v)!=null&&frame(v).clip().equals(expected)&&frame(v).weight()>.999&&RigAudit.bodies>0&&RigAudit.hands>0&&(!carry||RigAudit.shields>0));c.runOnClient(BowIdleRigClientTest::grip);check(c.computeOnClient(v->RigAudit.texture.equals(RigAudit.fixture.body().texturePath().toString())),"Real controlled native skin reaches GPU");c.takeScreenshot("bow-idle-real-"+type+"-"+arm+"-"+(carry?"carry":"empty"));c.runOnClient(v->v.options.setCameraType(CameraType.THIRD_PERSON_BACK));c.takeScreenshot("bow-idle-real-body-back-"+type+"-"+arm+"-"+(carry?"carry":"empty"));c.runOnClient(v->v.options.setCameraType(CameraType.THIRD_PERSON_FRONT));
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(!p.isUsingItem()&&p.getMainHandItem().getDamageValue()==0&&p.getInventory().getItem(10).getCount()==32&&p.getOffhandItem().getDamageValue()==0,"Idle source adds no bow use/ammo/wear/defense");});
            c.getInput().holdKey(v->v.keyUse);c.waitFor(v->v.player.isUsingItem()&&v.player.getUsedItemHand()==InteractionHand.MAIN_HAND);check(c.computeOnClient(v->frame(v)==null||!frame(v).clip().startsWith("bow_idle_")),"Actual native drawing owns hands immediately");c.takeScreenshot("bow-idle-native-draw-"+type+"-"+arm+"-"+(carry?"carry":"empty"));c.waitTicks(20);c.getInput().releaseKey(v->v.keyUse);c.waitFor(v->!v.player.isUsingItem()&&v.player.getMainHandItem().getDamageValue()==1);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(p.getInventory().getItem(10).getCount()==31&&p.getMainHandItem().getDamageValue()==1&&p.getOffhandItem().getDamageValue()==0,"Actual native bow release settles one arrow/one bow wear without carried-shield effects");});c.waitFor(v->frame(v)!=null&&frame(v).clip().equals(expected)&&frame(v).weight()>.999);c.takeScreenshot("bow-idle-return-after-native-shot-"+type+"-"+arm+"-"+(carry?"carry":"empty"));
        }
        prepare(c,w,PlayerModelType.WIDE,HumanoidArm.RIGHT,true);c.waitFor(v->frame(v)!=null);c.getInput().holdKey(WildcraftBindings.DEFEND);c.waitFor(v->v.player.isUsingItem()&&v.player.getUsedItemHand()==InteractionHand.OFF_HAND);check(c.computeOnClient(v->frame(v)==null),"Actual native shield use retains old body and item path");c.takeScreenshot("bow-idle-real-shield-use-owner");c.getInput().releaseKey(WildcraftBindings.DEFEND);c.waitFor(v->!v.player.isUsingItem());c.waitFor(v->frame(v)!=null);c.setScreen(()->new InventoryScreen(Minecraft.getInstance().player));check(c.computeOnClient(v->frame(v)==null),"Actual GUI owns idle bow");c.takeScreenshot("bow-idle-gui-owner");c.setScreen(()->null);
        prepare(c,w,PlayerModelType.WIDE,HumanoidArm.RIGHT,false);c.waitFor(v->frame(v)!=null);c.getInput().holdKey(v->v.keyUp);c.waitTicks(4);check(c.computeOnClient(v->frame(v)==null),"Actual movement retains original bow gait");c.takeScreenshot("bow-idle-native-moving");c.getInput().releaseKey(v->v.keyUp);
        prepare(c,w,PlayerModelType.WIDE,HumanoidArm.RIGHT,false);c.waitFor(v->frame(v)!=null);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.hurtServer(s.overworld(),p.damageSources().generic(),1);check(p.getHealth()<20,"Bow art grants no immunity");});c.waitFor(v->v.player.getHealth()<20&&MeleeActions.view(v.player).hurt()>0);check(c.computeOnClient(v->frame(v)==null),"Actual hurt owns body");c.takeScreenshot("bow-idle-real-hurt");
        prepare(c,w,PlayerModelType.WIDE,HumanoidArm.RIGHT,false);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.setItemSlot(EquipmentSlot.CHEST,new ItemStack(Items.IRON_CHESTPLATE));p.inventoryMenu.broadcastChanges();});c.waitFor(v->v.player.getItemBySlot(EquipmentSlot.CHEST).is(Items.IRON_CHESTPLATE));check(c.computeOnClient(v->frame(v)==null),"Actual armor remains native");c.takeScreenshot("bow-idle-native-armor");
        System.out.println("C6O actual mainhand native bow idle, wide/slim/left-right/empty or blue-glint-Fuse shield carry, skin/sprite wood-grip/axis/GPU, native real draw/one shot ammo-wear/return, shield use/GUI/movement/hurt/armor old paths PASS");
    }finally{c.getInput().releaseKey(v->v.keyUse);c.getInput().releaseKey(v->v.keyUp);c.getInput().releaseKey(WildcraftBindings.DEFEND);c.runOnClient(v->{RigAudit.enabled=false;RigAudit.fixture=null;DodgeFeedbackAudit.checkingNativeItem=false;v.options.setCameraType(CameraType.FIRST_PERSON);});}}
}
